const searchMessageEmbeddings = `-- name: SearchMessageEmbeddings :many
SELECT
    m.id, m.conversation_id, m.seq, m.role, m.event_type, m.content, m.token_count, m.created_at, m.actor_type, m.actor_id, m.source_session_id, m.inbox_id, m.origin_group_message_id,
    c.session_id AS session_id,
    c.title AS conversation_title,
    (1 - (e.embedding <=> $1::vector(1536)))::double precision AS score
FROM ctx_message_embedding e
JOIN ctx_message m ON m.id = e.message_id
JOIN ctx_conversation c ON c.id = m.conversation_id
WHERE e.model = $2
  AND c.user_id = $3
  AND c.agent_id IS NOT DISTINCT FROM $4
ORDER BY e.embedding <=> $1::vector(1536), m.created_at DESC, m.id DESC
LIMIT $5
`

type SearchMessageEmbeddingsParams struct {
	Query   pgvector_go.Vector `json:"query"`
	Model   string             `json:"model"`
	UserID  pgtype.Text        `json:"user_id"`
	AgentID pgtype.Text        `json:"agent_id"`
	Limit   int32              `json:"limit"`
}

type SearchMessageEmbeddingsRow struct {
	ID                   string      `json:"id"`
	ConversationID       string      `json:"conversation_id"`
	Seq                  int64       `json:"seq"`
	Role                 string      `json:"role"`
	EventType            string      `json:"event_type"`
	Content              string      `json:"content"`
	TokenCount           int64       `json:"token_count"`
	CreatedAt            time.Time   `json:"created_at"`
	ActorType            string      `json:"actor_type"`
	ActorID              pgtype.Text `json:"actor_id"`
	SourceSessionID      pgtype.Text `json:"source_session_id"`
	InboxID              pgtype.Text `json:"inbox_id"`
	OriginGroupMessageID pgtype.Text `json:"origin_group_message_id"`
	SessionID            string      `json:"session_id"`
	ConversationTitle    pgtype.Text `json:"conversation_title"`
	Score                float64     `json:"score"`
}

// Vector KNN over message embeddings, scoped to (user_id, agent_id) across every
// session like SearchMessages. WHERE model pins the query to a single vector
// space so a vector produced by a different model never matches; ORDER BY the
// <=> operator lets the HNSW cosine index drive the scan. score is cosine
// similarity (1 - distance), higher is better, matching the BM25 lane's score
// orientation for fusion. created_at, id break ties deterministically.
func (q *Queries) SearchMessageEmbeddings(ctx context.Context, arg SearchMessageEmbeddingsParams) ([]SearchMessageEmbeddingsRow, error) {
	rows, err := q.db.Query(ctx, searchMessageEmbeddings,
		arg.Query,
		arg.Model,
		arg.UserID,
		arg.AgentID,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchMessageEmbeddingsRow{}
	for rows.Next() {
		var i SearchMessageEmbeddingsRow
		if err := rows.Scan(
			&i.ID,
			&i.ConversationID,
			&i.Seq,
			&i.Role,
			&i.EventType,
			&i.Content,
			&i.TokenCount,
			&i.CreatedAt,
			&i.ActorType,
			&i.ActorID,
			&i.SourceSessionID,
			&i.InboxID,
			&i.OriginGroupMessageID,
			&i.SessionID,
			&i.ConversationTitle,
			&i.Score,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const searchMessages = `-- name: SearchMessages :many
SELECT
    m.id, m.conversation_id, m.seq, m.role, m.event_type, m.content, m.token_count, m.created_at, m.actor_type, m.actor_id, m.source_session_id, m.inbox_id, m.origin_group_message_id,
    c.session_id AS session_id,
    c.title AS conversation_title,
    paradedb.snippet(m.content)::text AS snippet,
    paradedb.score(m.id)::double precision AS score
FROM ctx_message m
JOIN ctx_conversation c ON c.id = m.conversation_id
WHERE m.id @@@ paradedb.match('content', $1::text)
  AND c.user_id = $2
  AND c.agent_id IS NOT DISTINCT FROM $3
ORDER BY score DESC, m.created_at DESC, m.id DESC
LIMIT $4
`

type SearchMessagesParams struct {
	Match   string      `json:"match"`
	UserID  pgtype.Text `json:"user_id"`
	AgentID pgtype.Text `json:"agent_id"`
	Limit   int32       `json:"limit"`
}

type SearchMessagesRow struct {
	ID                   string      `json:"id"`
	ConversationID       string      `json:"conversation_id"`
	Seq                  int64       `json:"seq"`
	Role                 string      `json:"role"`
	EventType            string      `json:"event_type"`
	Content              string      `json:"content"`
	TokenCount           int64       `json:"token_count"`
	CreatedAt            time.Time   `json:"created_at"`
	ActorType            string      `json:"actor_type"`
	ActorID              pgtype.Text `json:"actor_id"`
	SourceSessionID      pgtype.Text `json:"source_session_id"`
	InboxID              pgtype.Text `json:"inbox_id"`
	OriginGroupMessageID pgtype.Text `json:"origin_group_message_id"`
	SessionID            string      `json:"session_id"`
	ConversationTitle    pgtype.Text `json:"conversation_title"`
	Snippet              string      `json:"snippet"`
	Score                float64     `json:"score"`
}

// Spans every conversation of the current (user_id, agent_id) so memory recall
// survives across sessions. Joins ctx_conversation to pin the scope and surface
// provenance (session_id, title). Global ORDER BY score + LIMIT keeps the best
// matches across the merged corpus, not per-conversation truncations. Lexical
// ranking is pg_search BM25; paradedb.match tokenizes the raw user text with the
// jieba tokenizer (dictionary + statistical CJK word segmentation, so CJK matches
// natively with no fallback tier) and never errors on punctuation or query-syntax
// characters. The match arg is the raw user text. Multi-term queries are OR'd and
// ranked by BM25, which sinks weak partial matches below strong full matches.
// created_at, id break score ties deterministically: cross-source RRF uses each
// row's rank, so a stable order keeps the same query from reshuffling the merge.
func (q *Queries) SearchMessages(ctx context.Context, arg SearchMessagesParams) ([]SearchMessagesRow, error) {
	rows, err := q.db.Query(ctx, searchMessages,
		arg.Match,
		arg.UserID,
		arg.AgentID,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchMessagesRow{}
	for rows.Next() {
		var i SearchMessagesRow
		if err := rows.Scan(
			&i.ID,
			&i.ConversationID,
			&i.Seq,
			&i.Role,
			&i.EventType,
			&i.Content,
			&i.TokenCount,
			&i.CreatedAt,
			&i.ActorType,
			&i.ActorID,
			&i.SourceSessionID,
			&i.InboxID,
			&i.OriginGroupMessageID,
			&i.SessionID,
			&i.ConversationTitle,
			&i.Snippet,
			&i.Score,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const upsertMessageEmbedding = `-- name: UpsertMessageEmbedding :exec
INSERT INTO ctx_message_embedding (message_id, model, content_hash, embedding)
VALUES ($1, $2, $3, $4::vector(1536))
ON CONFLICT (message_id) DO UPDATE
SET model        = EXCLUDED.model,
    content_hash = EXCLUDED.content_hash,
    embedding    = EXCLUDED.embedding,
    updated_at   = now()
`

type UpsertMessageEmbeddingParams struct {
	MessageID   string             `json:"message_id"`
	Model       string             `json:"model"`
	ContentHash []byte             `json:"content_hash"`
	Embedding   pgvector_go.Vector `json:"embedding"`
}

// Write or replace the semantic-search vector for one message. model is the
// vector-space key every KNN query must filter on; content_hash is the hash of
// the embedded text so a later pass can spot rows whose source content changed.
// Keep this comment ASCII (sqlc rewriter offsets).
func (q *Queries) UpsertMessageEmbedding(ctx context.Context, arg UpsertMessageEmbeddingParams) error {
	_, err := q.db.Exec(ctx, upsertMessageEmbedding,
		arg.MessageID,
		arg.Model,
		arg.ContentHash,
		arg.Embedding,
	)
	return err
}
